import React, { useState } from 'react';
import { QUESTIONS, PLATFORM_QUESTIONS } from '../utils/questions';

export default function Questionnaire({ onSubmit }) {

  // ✅ NEW: USER DETAILS
  const [userData, setUserData] = useState({
    userId: "",
    age: "",
    gender: "",
    dailyScreenTime: "",
    sleepQuality: "",
    stressLevel: "",
    daysWithoutSocialMedia: "",
    exerciseFrequency: "",
    platform: "",
    happinessIndex: ""
  });

  const [answers, setAnswers] = useState({});
  const [platformUsage, setPlatformUsage] = useState({
    instagram: 0,
    youtube: 0,
    tiktok: 0,
    twitter: 0,
    facebook: 0,
    snapchat: 0,
  });

  const [selfRating, setSelfRating] = useState(5);
  const [current, setCurrent] = useState(0);

  // ✅ NEW PHASE ADDED
  const [phase, setPhase] = useState('userdata');

  const question = QUESTIONS?.[current];
  const totalQ = QUESTIONS.length;
  const answered = Object.keys(answers).length;

  const selectAnswer = (qId, score) => {
    setAnswers((prev) => ({
      ...prev,
      [String(qId)]: score,
    }));

    setTimeout(() => {
      if (current < totalQ - 1) {
        setCurrent((c) => c + 1);
      } else {
        setPhase('platform');
      }
    }, 200);
  };

  // ✅ FINAL SUBMIT
  const handleSubmit = () => {
    onSubmit({
      ...userData,   // ⭐ IMPORTANT
      answers,
      platformUsage,
      selfRating,
    });
  };

  const progress =
    phase === 'userdata' ? 10 :
    phase === 'questions' ? 40 :
    phase === 'platform' ? 70 :
    phase === 'selfrating' ? 90 : 100;

  return (
    <div className="max-w-2xl mx-auto">

      {/* ================= USER DATA ================= */}
      {phase === 'userdata' && (
        <div className="card">
          <h2 className="text-white text-xl mb-6">User Details</h2>

          <input placeholder="User ID"
            onChange={(e)=>setUserData({...userData, userId:e.target.value})} />

          <input type="number" placeholder="Age"
            onChange={(e)=>setUserData({...userData, age:e.target.value})} />

          <select onChange={(e)=>setUserData({...userData, gender:e.target.value})}>
            <option value="">Select Gender</option>
            <option>Male</option>
            <option>Female</option>
            <option>Other</option>
          </select>

          <input type="number" placeholder="Daily Screen Time (hrs)"
            onChange={(e)=>setUserData({...userData, dailyScreenTime:e.target.value})} />

          <input type="number" placeholder="Sleep Quality (1-10)"
            onChange={(e)=>setUserData({...userData, sleepQuality:e.target.value})} />

          <input type="number" placeholder="Stress Level (1-10)"
            onChange={(e)=>setUserData({...userData, stressLevel:e.target.value})} />

          <input type="number" placeholder="Days Without Social Media"
            onChange={(e)=>setUserData({...userData, daysWithoutSocialMedia:e.target.value})} />

          <input type="number" placeholder="Exercise Frequency (week)"
            onChange={(e)=>setUserData({...userData, exerciseFrequency:e.target.value})} />

          <select onChange={(e)=>setUserData({...userData, platform:e.target.value})}>
            <option value="">Select Platform</option>
            <option>Facebook</option>
            <option>Instagram</option>
            <option>YouTube</option>
            <option>LinkedIn</option>
            <option>X (Twitter)</option>
          </select>

          <input type="number" placeholder="Happiness Index (1-10)"
            onChange={(e)=>setUserData({...userData, happinessIndex:e.target.value})} />

          <button
            onClick={()=>setPhase('questions')}
            className="btn-primary w-full mt-4"
          >
            Next
          </button>
        </div>
      )}

      {/* ================= QUESTIONS ================= */}
      {phase === 'questions' && question && (
        <div className="card">
          <h2 className="text-white text-xl mb-6">
            Q{current + 1}. {question.text}
          </h2>

          {question.options.map((opt, i) => (
            <button
              key={i}
              onClick={() => selectAnswer(question.id, opt.score)}
              className="btn-secondary w-full mb-2"
            >
              {opt.label}
            </button>
          ))}
        </div>
      )}

      {/* ================= PLATFORM ================= */}
      {phase === 'platform' && (
        <div className="card">
          <h2 className="text-white text-xl mb-6">Platform Usage</h2>

          {PLATFORM_QUESTIONS.map((p) => (
            <div key={p.id}>
              <label>{p.label}</label>
              <input
                type="range"
                min="0"
                max="10"
                value={platformUsage[p.id]}
                onChange={(e) =>
                  setPlatformUsage({
                    ...platformUsage,
                    [p.id]: Number(e.target.value),
                  })
                }
              />
            </div>
          ))}

          <button onClick={()=>setPhase('selfrating')} className="btn-primary">
            Next
          </button>
        </div>
      )}

      {/* ================= SELF ================= */}
      {phase === 'selfrating' && (
        <div className="card">
          <h2>Self Rating</h2>

          <input type="range" min="1" max="10"
            value={selfRating}
            onChange={(e)=>setSelfRating(Number(e.target.value))}
          />

          <button onClick={()=>setPhase('review')} className="btn-primary">
            Next
          </button>
        </div>
      )}

      {/* ================= REVIEW ================= */}
      {phase === 'review' && (
        <div className="card">
          <button onClick={handleSubmit} className="btn-primary">
            Submit Data
          </button>
        </div>
      )}

    </div>
  );
}
